create table if not exists universes(id uuid primary key,name text not null,state_json jsonb not null,created_at timestamptz not null,updated_at timestamptz not null);
create table if not exists simulation_events(id uuid primary key,universe_id uuid not null references universes(id) on delete cascade,tick bigint not null,year double precision not null,type text not null,importance integer not null,summary text not null,details text not null,actor_id uuid null,location_id uuid null,caused_by_event_id uuid null references simulation_events(id),recorded_at timestamptz not null);
create index if not exists ix_events_universe_tick on simulation_events(universe_id,tick desc); create index if not exists ix_events_importance on simulation_events(universe_id,importance,tick desc);
